def raw_exercise():
    L = ['مشق', '', '۱۔ متن کے حوالے سے خالی جگہ پُر کریں۔']
    L += [f'({r}) {s}' for r, (s, _) in zip(['i', 'ii', 'iii', 'iv', 'v', 'vi', 'vii', 'viii'], BLANKS)]
    nums = ['۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹']
    L += [''] + [f'{n}۔ {q}' for n, (q, _) in zip(nums, QS[:8])]
    L += ['۱۰۔ مندرجہ ذیل محاورات اور الفاظ و تراکیب کو اپنے جملوں میں اس طرح استعمال کریں کہ ان کا مطلب واضح ہو جائے۔', '، '.join(w for w, _, _ in VOCAB) + '۔']
    L += [f'۱۱۔ {QS[8][0]}', f'۱۲۔ سیاق و سباق کا حوالہ دے کر مندرجہ ذیل اقتباس کی وضاحت کریں۔', PASSAGE]
    L += ['', ACTIVITY, '', TEACHER]
    return '\n'.join(L)


def fix_exercise(ex):
    ex['rawExercise'] = raw_exercise()
    ex['blanks'] = [dict(statement=s, answer=a) for s, a in BLANKS]
    ex['shortQuestions'] = [dict(question=q, answer=a) for q, a in QS]
    ex['vocabulary'] = [dict(word=w, meaning=m, sentence=s) for w, m, s in VOCAB]
    ex['grammar'] = GRAMMAR
    ex['activity'] = ACTIVITY.split(': ', 1)[1]
    ex['teacherInstructions'] = [TEACHER.split(': ', 1)[1]]
    ex['answerNote'] = 'SpaceBook answers (the textbook prints no answers).'
    ex.pop('contextualTashreeh', None)


